package net.officefloor.hq.app.claim;

import java.util.Set;

/** A status change, named as in the path: the statuses it may be taken from, the status it moves
 *  the claim to and the audit event it writes. A settle the clerk limit sends to PENDING writes CLAIM_PENDING. */
public enum ClaimAction {
    OPEN(Set.of(ClaimStatus.DRAFT), ClaimStatus.OPEN, "CLAIM_OPENED"),
    SETTLE(Set.of(ClaimStatus.OPEN), ClaimStatus.SETTLED, "CLAIM_SETTLED"),
    APPROVE(Set.of(ClaimStatus.PENDING), ClaimStatus.SETTLED, "CLAIM_APPROVED"),
    REJECT(Set.of(ClaimStatus.PENDING), ClaimStatus.OPEN, "CLAIM_REJECTED"),
    VOID(Set.of(ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING), ClaimStatus.VOID, "CLAIM_VOIDED");

    /** The event of a settle the clerk limit sent to PENDING. */
    public static final String PENDING_EVENT = "CLAIM_PENDING";

    private final Set<ClaimStatus> from;
    private final ClaimStatus to;
    private final String event;

    ClaimAction(Set<ClaimStatus> from, ClaimStatus to, String event) {
        this.from = from;
        this.to = to;
        this.event = event;
    }

    public boolean allowedFrom(ClaimStatus status) { return from.contains(status); }
    public ClaimStatus to() { return to; }
    public String event() { return event; }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.hq.app.setting.PolicyDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim its number (see {@link ClaimNumbering}), which it keeps when voided. Settling fixes the claim's
 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
 *  Both are rounded by the claim's rounding (see {@link PolicyDate}).
 *  The user who opened a claim may not settle it (four eyes).
 *  Only a steward approves or rejects a PENDING claim, and never the user who opened it approves it. Approving
 *  fixes the due at its live figure of that moment (a PENDING claim is not bound by a statement), late charge
 *  frozen in; rejecting needs a reason and moves the claim back to OPEN, bound again by its statement.
 *  Publishes the number the audit line carries. */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimNumbering numbering,
            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, PolicyDate policyDate,
            RoleRepository roles, Out<ClaimNumber> numberOut,
            @RequestParam(value = "user", required = false) String user,
            @RequestParam(value = "reason", required = false) String reason)
            throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
        }
        if ((action == ClaimAction.APPROVE || action == ClaimAction.REJECT)
                && !Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new InvalidClaimStatusException("Only a steward can " + action.name().toLowerCase(Locale.ROOT)
                    + " a PENDING claim.");
        }
        if (action == ClaimAction.APPROVE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot approve it.");
        }
        if (action == ClaimAction.REJECT && (reason == null || reason.isBlank())) {
            throw new InvalidClaimStatusException("A reason is needed to reject a claim.");
        }
        // The late charge is worked out while the claim is still OPEN (or PENDING), so settling freezes it in.
        boolean fixes = action == ClaimAction.SETTLE || action == ClaimAction.APPROVE;
        RoundingMode mode = !fixes ? null : policyDate.of(claim.getSheetId()).modeFor(claim);
        BigDecimal settledDue = !fixes ? null : latePct.of(claim.getSheetId())
                .addTo(claim, claim.isBound() ? claim.getStatedDue() : dueNow(claim, people, rates, floor, mode), mode);
        claim.setStatus(action.to());
        switch (action) {
            case OPEN -> {
                claim.setNumber(numbering.next(claim));
                claim.setOpenedBy(user);
            }
            case SETTLE, APPROVE -> claim.setSettledDue(settledDue);
            default -> { }
        }
        numberOut.set(new ClaimNumber(claim.getNumber()));
    }

    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor; null when no rate is in force on the claim's date. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor, RoundingMode mode) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        return Floor.raise(claim, Rate.inForce(rates.findBySheet(claim.getSheetId()), person.gradeOn(claim.getDate()), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
                .orElse(null), floor.of(claim.getSheetId()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.Locale;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class ValidateClaimAction {
    public void validate(@PathVariable("action") String action, Out<ClaimAction> actionOut)
            throws InvalidClaimException {
        try {
            actionOut.set(ClaimAction.valueOf(action.toUpperCase(Locale.ROOT)));
        } catch (IllegalArgumentException e) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses opening, settling or voiding a claim dated inside a closed period. */
public class CheckClaimActionOpen {
    public void check(@Val Claim claim, PeriodRepository periods) throws InvalidClaimStatusException {
        var closed = periods.closedOn(claim.getSheetId(), claim.getDate());
        if (closed.isPresent()) {
            throw new InvalidClaimStatusException(ClosedPeriods.message(closed.get().name()));
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim's status change once it is allowed and saved; a settle or approve adds the due it fixed
 *  (n/a without a rate), a reject its reason. A settle the clerk limit sent to PENDING is CLAIM_PENDING, with no due. */
public class AuditClaimStatus {
    public void audit(@Val ClaimAction action, @Val Claim claim, @Val ClaimNumber number,
            @RequestParam(value = "user", required = false) String user,
            @RequestParam(value = "reason", required = false) String reason, PersonRepository people, Audit audit) {
        String event = action == ClaimAction.SETTLE && claim.getStatus() == ClaimStatus.PENDING
                ? ClaimAction.PENDING_EVENT : action.event();
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        audit.record(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
                + number.auditField()
                + (claim.getStatus() == ClaimStatus.SETTLED ? " due=" + (claim.getSettledDue() == null ? "n/a"
                        : claim.getSettledDue().toPlainString()) : "")
                + (action == ClaimAction.REJECT ? " reason=" + reason.trim() : ""));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            ClaimRepository repository, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = repository.findById(sheetId, claimId);
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, ClaimRepository repository) {
        repository.save(claim);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim made by a person on a sheet. Mutable so an Apply step changes it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy,
            boolean stated, BigDecimal statedDue, String corrects) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on the sheet: null for a draft (a voided claim keeps its number). */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when the claim was settled: null while it is live (not settled, or settled without a rate). */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened the claim: null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether the person's last statement bound the claim to {@link #getStatedDue()}. */
    public boolean isStated() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    /** The figure the last statement bound the claim to: null when unbound, or bound without a rate (n/a). */
    public BigDecimal getStatedDue() { return statedDue; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    /** Whether the statement binding holds now: stated, and not PENDING (a PENDING claim keeps its binding
     *  but follows its live figure until it is rejected back to OPEN). */
    public boolean isBound() { return stated && status != ClaimStatus.PENDING; }
    /** The number of the SETTLED claim this correction (a negative amount) corrects: null for any other claim. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** Whether the claim is a correction: its due has no floor and no late charge. */
    public boolean isCorrection() { return corrects != null; }
}

